insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  23,
  $wyb$A contract analysis tool that reads a PDF or DOCX contract, sends the text to the AI with a 15-clause taxonomy, extracts the exact text and a plain-English summary plus a red/yellow/green risk rating for each clause type, and can compare two contracts side by side. A quote-verification guard checks every claimed 'exact quote' against the real contract text -- a hallucinated quote in a legal-review tool is a serious problem, not a cosmetic one -- and flags anything that doesn't actually appear in the source.$wyb$,
  $wyl$[
  "Extract text from PDF and DOCX contracts, keeping structural newlines intact",
  "Define a clause taxonomy and know it needs adjusting per contract type",
  "Verify an AI's claimed verbatim quote actually exists in the source document, not just trust it",
  "Normalize a risk rating against a fixed rubric instead of leaving the judgment open-ended",
  "Roll up per-clause risk into one overall rating with a simple, explainable rule",
  "Flag deviations from a standard clause library, and know the limits of a word-prefix heuristic"
]$wyl$::jsonb,
  $sess${
  "model": "Gemini 3.6 Flash or Claude Haiku 4.5 (your choice - see sdt_ai.py setup)",
  "totalTime": "125 min",
  "buildCount": 4,
  "whatYouNeed": [
    "A free Gemini API key (aistudio.google.com/apikey) OR your own Claude/Anthropic API key (console.anthropic.com/settings/keys)",
    "Python 3.10+ installed",
    "A few sample contracts (PDF or DOCX) - NDAs, vendor agreements, etc."
  ],
  "outcomes": [
    "Read PDF or DOCX contracts and pull out 15 key clause types automatically",
    "Verify every claimed exact quote actually exists in the source contract, not just trust it",
    "Normalize risk ratings against a fixed rubric so they're consistent and explainable",
    "Roll up per-clause risk into one overall contract risk level with a simple, auditable rule",
    "Flag deviations from a standard clause library, and know the limits of a word-prefix heuristic",
    "Compare two contract versions and export a color-coded Word document for legal review"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Build the contract reader and clause taxonomy",
      "time": "25 min",
      "description": "Get plain text out of any contract file and define the 15 clause types you want extracted every time.",
      "steps": [
        {
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future AI Builder project:",
          "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# Overridable via .env if you ever want to try a different model.\nGEMINI_MODEL = os.environ.get(\"GEMINI_MODEL\", \"gemini-2.5-flash\")\nGEMINI_URL = (\n    f\"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent\"\n)\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Gemini's free tier occasionally answers 503 (\"model overloaded\") during\n# busy periods - that's not your code being wrong, retrying a couple of\n# times almost always gets a real answer.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": {\"maxOutputTokens\": max_tokens},\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    last_problem = \"no response\"\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(\n                GEMINI_URL, params={\"key\": api_key}, json=payload, timeout=90\n            )\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            )\n\n        if response.status_code == 503:\n            last_problem = \"Gemini is busy (503 - high demand on the free tier)\"\n            time.sleep(RETRY_DELAY_SECONDS)\n            continue\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again.\"\n            )\n\n        if response.status_code == 400:\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        try:\n            candidate = data[\"candidates\"][0]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n\n        if candidate.get(\"finishReason\") == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        try:\n            text = candidate[\"content\"][\"parts\"][0][\"text\"]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply shape from Gemini: {data}\")\n\n        usage = data.get(\"usageMetadata\", {})\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n    raise AIError(\n        f\"Gemini was unavailable after {MAX_ATTEMPTS} tries ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    try:\n        response = requests.post(\n            ANTHROPIC_URL,\n            headers={\n                \"x-api-key\": api_key,\n                \"anthropic-version\": ANTHROPIC_VERSION,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\"Could not reach Claude. Check your internet connection and try again.\")\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\")\n\n    if response.status_code == 401:\n        raise AIError(\n            \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n        )\n\n    if response.status_code == 429:\n        raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n    if \"error\" in data:\n        raise AIError(data[\"error\"].get(\"message\", str(data[\"error\"])))\n\n    text = \"\".join(\n        block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n    )\n    usage = data.get(\"usage\", {})\n    return {\n        \"text\": text,\n        \"input_tokens\": usage.get(\"input_tokens\"),\n        \"output_tokens\": usage.get(\"output_tokens\"),\n    }\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        provider = _get_provider()\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider}\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first."
        },
        {
          "instruction": "Create `.env` in the same folder with this content, then replace the placeholders with your real keys:",
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented."
        },
        {
          "instruction": "Create `reader.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the Contract Clause Extractor (part 1).\n\nExtracts plain text from a PDF or DOCX contract. Newlines are kept\nintact since contracts use them as structural cues (section breaks,\nnumbered clauses) that the AI can use to navigate the document.\n\"\"\"\n\nfrom PyPDF2 import PdfReader\nfrom docx import Document\n\n\ndef read_contract(path):\n    \"\"\"\n    Reads a .pdf or .docx contract and returns its text, or raises\n    ValueError for any other extension.\n\n        text = read_contract(\"nda.pdf\")\n    \"\"\"\n    if path.lower().endswith(\".pdf\"):\n        reader = PdfReader(path)\n        return \"\\n\".join(page.extract_text() or \"\" for page in reader.pages)\n\n    if path.lower().endswith(\".docx\"):\n        document = Document(path)\n        return \"\\n\".join(paragraph.text for paragraph in document.paragraphs)\n\n    raise ValueError(f\"Unsupported file type: {path}. This project reads .pdf and .docx only.\")\n\n\nif __name__ == \"__main__\":\n    print(\"This file only wraps real PDF/DOCX reads from disk - there's no\")\n    print(\"offline self-test here. Run it against a real sample contract in Build 1's\")\n    print(\"verify step, once you have one.\")\n",
          "verify": "This file only wraps real PDF/DOCX reads - there's no offline self-test to run here."
        },
        {
          "instruction": "Create `taxonomy.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the Contract Clause Extractor (part 2) - the 15 clause types\nthis project looks for in every contract.\n\nAdjust this list per contract type: an NDA needs different clauses than\na vendor services agreement (an NDA rarely has \"Payment Terms\"; a vendor\nagreement rarely has \"Non-Compete\"). This default list is a reasonable\nstarting point for a general commercial agreement, not a fixed standard.\n\"\"\"\n\nCLAUSE_TYPES = [\n    \"Payment Terms\",\n    \"Termination\",\n    \"Limitation of Liability\",\n    \"Indemnification\",\n    \"Intellectual Property Ownership\",\n    \"Confidentiality\",\n    \"Governing Law\",\n    \"Dispute Resolution\",\n    \"Auto-Renewal\",\n    \"Assignment\",\n    \"Warranties\",\n    \"Force Majeure\",\n    \"Non-Compete\",\n    \"Data Protection\",\n    \"Insurance Requirements\",\n]\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the taxonomy is well-formed:\n    #     python taxonomy.py\n    assert len(CLAUSE_TYPES) == 15\n    assert len(CLAUSE_TYPES) == len(set(CLAUSE_TYPES))  # no accidental duplicates\n    print(f\"Taxonomy has {len(CLAUSE_TYPES)} clause types, all unique:\")\n    for clause_type in CLAUSE_TYPES:\n        print(\" -\", clause_type)\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python taxonomy.py`. You should see all 15 clause types printed with no duplicates, ending with `All checks passed.`"
        },
        {
          "instruction": "Now run read_contract() on a real sample PDF and a real sample DOCX:",
          "prompt": "python -c \"from reader import read_contract; print(read_contract('sample_contract.pdf')[:500])\"",
          "verify": "Both should print readable text with section breaks visible as newlines."
        }
      ],
      "goFurther": "🛠️ Add a third file type - plain .txt - to reader.py for contracts you've already converted."
    },
    {
      "number": 2,
      "title": "Build the extractor with a quote-verification guard",
      "time": "40 min",
      "description": "Send the contract text to the AI and get back structured data for every clause type. This build's safety guard checks every claimed exact quote against the real contract text - a hallucinated quote in a legal-review tool would be a serious, not cosmetic, problem.",
      "steps": [
        {
          "instruction": "Create `extract.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the Contract Clause Extractor.\n\nSends the contract text to the AI and gets back structured data for\nevery clause type: an exact quote, a plain-English summary, and a risk\nrating. This project's safety guard verifies that each claimed \"exact\nquote\" actually appears in the source contract - a hallucinated quote\nin a legal-review tool is a serious problem, not a cosmetic one.\n\"\"\"\n\nimport json\n\nfrom sdt_ai import ask_ai\n\nVALID_RISK_LEVELS = {\"red\", \"yellow\", \"green\"}\n\n# Stop sending contract text after this many characters. Longer\n# contracts should be split in half and the JSON results merged (see\n# this build's goFurther) - this cap is a reasonable ceiling for a\n# typical 10-20 page commercial agreement.\nMAX_CHARACTERS = 12000\n\nRISK_RUBRIC = \"\"\"Rate each clause's risk using this rubric:\nred    - unusual or unfavorable to our side (e.g. uncapped liability, one-sided termination rights)\nyellow - present but worth a second look (e.g. vague timelines, ambiguous scope)\ngreen  - standard, favorable, or industry-typical language\"\"\"\n\n\ndef build_prompt(contract_text, clause_types):\n    trimmed = contract_text[:MAX_CHARACTERS]\n    clause_list = \"\\n\".join(f\"- {c}\" for c in clause_types)\n\n    return f\"\"\"Below is a contract. For each clause type listed, find:\n- exact_text: a VERBATIM quote from the contract below, copied exactly\n  (or the string \"Not found\" if this contract has no such clause - never\n  paraphrase or invent text that isn't literally present)\n- summary: one plain-English sentence explaining what it means\n- risk: red, yellow, or green\n\n{RISK_RUBRIC}\n\nCLAUSE TYPES:\n{clause_list}\n\nReturn ONLY this JSON shape, no markdown code fence, no explanation:\n{{\"clauses\": {{\"<clause type>\": {{\"exact_text\": \"...\", \"summary\": \"...\", \"risk\": \"...\"}}}}}}\n\nCONTRACT TEXT:\n{trimmed}\"\"\"\n\n\ndef parse_extraction_reply(reply):\n    \"\"\"Defensive JSON parsing, same pattern used throughout this course. Returns None on real garbage.\"\"\"\n    cleaned = reply.strip()\n    if cleaned.startswith(\"```\"):\n        lines = cleaned.splitlines()[1:]\n        if lines and lines[-1].strip() == \"```\":\n            lines = lines[:-1]\n        cleaned = \"\\n\".join(lines)\n\n    try:\n        return json.loads(cleaned)\n    except json.JSONDecodeError:\n        return None\n\n\ndef _normalize_for_matching(text):\n    \"\"\"Collapses whitespace so a quote spanning a line break still matches the source text.\"\"\"\n    return \" \".join(text.split())\n\n\ndef verify_exact_text(clauses, contract_text):\n    \"\"\"\n    Checks every clause's exact_text against the actual contract text,\n    and adds a \"verified\" boolean to each clause.\n\n        verify_exact_text(clauses, contract_text)\n\n    A clause marked \"Not found\" is always verified=True - there's\n    nothing to check, since the AI is explicitly saying it found no such\n    clause. Everything else must appear, after whitespace normalization,\n    as a literal substring of the contract - if it doesn't, \"verified\"\n    is set to False so a lawyer knows to double-check that quote by hand\n    rather than trusting it at face value. This never changes exact_text\n    itself, it only flags it.\n    \"\"\"\n    normalized_contract = _normalize_for_matching(contract_text)\n\n    for clause_type, data in clauses.items():\n        exact_text = data.get(\"exact_text\", \"\")\n        if exact_text.strip().lower() == \"not found\":\n            data[\"verified\"] = True\n            continue\n\n        data[\"verified\"] = _normalize_for_matching(exact_text) in normalized_contract\n\n    return clauses\n\n\ndef validate_risk_levels(clauses):\n    \"\"\"\n    Normalizes each clause's risk value against VALID_RISK_LEVELS -\n    anything the AI wrote that isn't cleanly red/yellow/green becomes\n    \"unclear\" rather than silently being treated as, say, \"green\" by a\n    downstream string comparison that happens not to match anything.\n    \"\"\"\n    for data in clauses.values():\n        risk = str(data.get(\"risk\", \"\")).strip().lower()\n        data[\"risk\"] = risk if risk in VALID_RISK_LEVELS else \"unclear\"\n    return clauses\n\n\ndef extract_clauses(contract_text, clause_types):\n    \"\"\"\n    The main function. Give it the contract text and a list of clause\n    types, get back a validated {clause_type: {...}} dict - every quote\n    checked against the source, every risk level normalized.\n    \"\"\"\n    prompt = build_prompt(contract_text, clause_types)\n    reply = ask_ai(prompt, max_tokens=4000, project=\"contract-clause-extractor\")\n\n    parsed = parse_extraction_reply(reply)\n    if parsed is None or \"clauses\" not in parsed:\n        raise ValueError(\n            \"The AI's reply wasn't valid JSON in the expected shape.\\n\"\n            \"Run it again - this usually fixes itself.\\n\"\n            \"If it keeps happening, print(reply) to see what came back.\"\n        )\n\n    clauses = parsed[\"clauses\"]\n    clauses = validate_risk_levels(clauses)\n    clauses = verify_exact_text(clauses, contract_text)\n    return clauses\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check parsing and both guards work -\n    # no AI call, no credits spent:  python extract.py\n    contract_text = (\n        \"This Agreement shall be governed by the laws of the State of Delaware. \"\n        \"Payment is due within 30 days of invoice.\"\n    )\n\n    print(\"Checking verify_exact_text() with a real quote...\")\n    clauses = {\"Governing Law\": {\"exact_text\": \"governed by the laws of the State of Delaware\", \"risk\": \"green\"}}\n    result = verify_exact_text(clauses, contract_text)\n    assert result[\"Governing Law\"][\"verified\"] is True\n    print(\"  OK - a real substring verified True\")\n\n    print(\"\\nChecking verify_exact_text() with a hallucinated quote...\")\n    clauses = {\"Non-Compete\": {\"exact_text\": \"Employee shall not compete for 5 years after termination\", \"risk\": \"red\"}}\n    result = verify_exact_text(clauses, contract_text)\n    assert result[\"Non-Compete\"][\"verified\"] is False\n    print(\"  OK - text that never appears in the contract correctly flagged verified=False\")\n\n    print(\"\\nChecking verify_exact_text() treats 'Not found' as always verified...\")\n    clauses = {\"Insurance Requirements\": {\"exact_text\": \"Not found\", \"risk\": \"green\"}}\n    result = verify_exact_text(clauses, contract_text)\n    assert result[\"Insurance Requirements\"][\"verified\"] is True\n    print(\"  OK\")\n\n    print(\"\\nChecking validate_risk_levels() normalizes an unrecognised risk value...\")\n    clauses = {\"Payment Terms\": {\"risk\": \"Moderate\"}}\n    result = validate_risk_levels(clauses)\n    assert result[\"Payment Terms\"][\"risk\"] == \"unclear\"\n    print(\"  OK - 'Moderate' correctly normalized to 'unclear' instead of silently passing through\")\n\n    print(\"\\nChecking parse_extraction_reply() strips a ```json code fence...\")\n    fenced = '```json\\n{\"clauses\": {}}\\n```'\n    assert parse_extraction_reply(fenced) == {\"clauses\": {}}\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python extract.py` (no AI call, no credits spent - this only tests parsing and both guards against fake data). You should see a real quote correctly verified True, a hallucinated quote correctly flagged verified=False, a 'Not found' clause correctly always verified True, an unrecognised risk value ('Moderate') correctly normalized to 'unclear', and a ```json-fenced reply correctly parsed - ending with `All checks passed.`"
        },
        {
          "instruction": "Now run it on a real sample contract:",
          "prompt": "python -c \"from reader import read_contract; from taxonomy import CLAUSE_TYPES; from extract import extract_clauses; import json; text = read_contract('sample_contract.pdf'); print(json.dumps(extract_clauses(text, CLAUSE_TYPES), indent=2))\"",
          "verify": "You should get back a dict with all 15 clause types, each with exact_text, summary, risk, and verified. Check whether any came back verified=False - if so, read that clause by hand to see whether the AI paraphrased instead of quoting verbatim."
        }
      ],
      "goFurther": "🛠️🛠️ For a 50+ page contract, split contract_text into two halves, run extract_clauses() on each with the same clause_types, and merge the two results by clause type (prefer whichever half found the clause, or 'Not found' only if both did)."
    },
    {
      "number": 3,
      "title": "Score overall risk and check against your standards",
      "time": "25 min",
      "description": "Roll up clause-level risk into one overall rating, and flag clauses that deviate from your organization's standard language.",
      "steps": [
        {
          "instruction": "Create `risk.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the Contract Clause Extractor (part 1) - rolls up per-clause\nrisk ratings into one overall contract risk level.\n\"\"\"\n\n\ndef count_risk_levels(clauses):\n    \"\"\"Pure function - counts red/yellow/green/unclear across all clauses.\"\"\"\n    counts = {\"red\": 0, \"yellow\": 0, \"green\": 0, \"unclear\": 0}\n    for data in clauses.values():\n        risk = data.get(\"risk\", \"unclear\")\n        counts[risk] = counts.get(risk, 0) + 1\n    return counts\n\n\ndef overall_risk(clauses):\n    \"\"\"\n    Returns \"High Risk\", \"Medium Risk\", or \"Low Risk\" based on how many\n    clauses are rated red/yellow.\n\n        overall_risk(clauses)\n\n    Rule: 2+ red -> High Risk. 1 red OR 4+ yellow -> Medium Risk.\n    Otherwise -> Low Risk. Deliberately simple and explainable - a\n    lawyer using this tool can recompute the same rating by hand from\n    the counts alone, which matters more here than a more \"clever\" but\n    opaque scoring formula would.\n    \"\"\"\n    counts = count_risk_levels(clauses)\n\n    if counts[\"red\"] >= 2:\n        return \"High Risk\"\n    if counts[\"red\"] == 1 or counts[\"yellow\"] >= 4:\n        return \"Medium Risk\"\n    return \"Low Risk\"\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the roll-up logic works - no AI\n    # call, no credits spent:  python risk.py\n    print(\"Checking 2+ red clauses -> High Risk...\")\n    two_red = {f\"clause{i}\": {\"risk\": \"red\"} for i in range(2)}\n    assert overall_risk(two_red) == \"High Risk\"\n    print(\"  OK\")\n\n    print(\"\\nChecking exactly 1 red clause -> Medium Risk...\")\n    one_red = {\"clause1\": {\"risk\": \"red\"}, \"clause2\": {\"risk\": \"green\"}}\n    assert overall_risk(one_red) == \"Medium Risk\"\n    print(\"  OK\")\n\n    print(\"\\nChecking 4+ yellow (no red) -> Medium Risk...\")\n    four_yellow = {f\"clause{i}\": {\"risk\": \"yellow\"} for i in range(4)}\n    assert overall_risk(four_yellow) == \"Medium Risk\"\n    print(\"  OK\")\n\n    print(\"\\nChecking mostly green, a couple yellow -> Low Risk...\")\n    mostly_green = {\"c1\": {\"risk\": \"green\"}, \"c2\": {\"risk\": \"green\"}, \"c3\": {\"risk\": \"yellow\"}}\n    assert overall_risk(mostly_green) == \"Low Risk\"\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python risk.py`. You should see 2+ red clauses correctly producing High Risk, exactly 1 red producing Medium Risk, 4+ yellow with no red also producing Medium Risk, and a mostly-green set producing Low Risk - ending with `All checks passed.`"
        },
        {
          "instruction": "Create `standard_library.py` with this code, then edit STANDARD_CLAUSES to match your own organization's preferred language:",
          "prompt": "\"\"\"\nStep 3 of the Contract Clause Extractor (part 2) - flags clauses that\ndeviate from your organization's standard language.\n\"\"\"\n\nSTANDARD_CLAUSES = {\n    \"Limitation of Liability\": \"Liability shall not exceed fees paid in the preceding 12 months.\",\n    \"Governing Law\": \"This agreement shall be governed by the laws of Delaware.\",\n}\n\n\ndef flag_deviations(clauses, standard_clauses=STANDARD_CLAUSES):\n    \"\"\"\n    Compares the first 3 words of each standard clause against the\n    first 3 words of the actual extracted clause, and returns a dict of\n    deviations with both the standard and actual text for any mismatch.\n\n        flag_deviations(clauses)\n\n    The word-prefix check is a starting heuristic, not a semantic\n    comparison - it catches wording that opens noticeably differently,\n    but two clauses that start the same way and diverge in the middle\n    would slip past it. Production use should ask the AI to assess\n    semantic similarity instead (see this build's goFurther).\n    \"\"\"\n    deviations = {}\n\n    for clause_type, standard_text in standard_clauses.items():\n        actual = clauses.get(clause_type, {}).get(\"exact_text\", \"\")\n        if actual.strip().lower() == \"not found\":\n            deviations[clause_type] = {\"standard\": standard_text, \"actual\": \"Not found in contract\"}\n            continue\n\n        standard_prefix = \" \".join(standard_text.split()[:3]).lower()\n        actual_prefix = \" \".join(actual.split()[:3]).lower()\n\n        if standard_prefix != actual_prefix:\n            deviations[clause_type] = {\"standard\": standard_text, \"actual\": actual}\n\n    return deviations\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the deviation logic works - no\n    # AI call, no credits spent:  python standard_library.py\n    print(\"Checking a clause matching the standard's opening words...\")\n    matching = {\"Governing Law\": {\"exact_text\": \"This agreement shall be governed by the laws of Texas, not Delaware.\"}}\n    result = flag_deviations(matching)\n    assert \"Governing Law\" not in result\n    print(\"  OK - same opening 3 words, not flagged (even though the state differs later in the sentence -\")\n    print(\"  this IS the heuristic's known limitation, and exactly why the goFurther suggests a semantic check)\")\n\n    print(\"\\nChecking a clause with a genuinely different opening...\")\n    different = {\"Limitation of Liability\": {\"exact_text\": \"In no event shall either party be liable for any damages.\"}}\n    result = flag_deviations(different)\n    assert \"Limitation of Liability\" in result\n    assert result[\"Limitation of Liability\"][\"actual\"].startswith(\"In no event\")\n    print(\"  OK -\", result[\"Limitation of Liability\"])\n\n    print(\"\\nChecking a clause the AI couldn't find at all is flagged as a deviation...\")\n    missing = {\"Governing Law\": {\"exact_text\": \"Not found\"}}\n    result = flag_deviations(missing)\n    assert result[\"Governing Law\"][\"actual\"] == \"Not found in contract\"\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python standard_library.py`. You should see a clause matching the standard's opening words correctly NOT flagged, a genuinely different opening correctly flagged with both texts shown, and a clause the AI couldn't find at all correctly flagged as a deviation - ending with `All checks passed.`"
        }
      ],
      "goFurther": "🛠️🛠️ Replace flag_deviations()'s word-prefix check with an AI call that rates semantic similarity 0-100 between the standard clause and the actual clause, and flags anything below a threshold you choose."
