    {
      "number": 4,
      "title": "Add contract comparison and export to Word",
      "time": "35 min",
      "description": "Compare two contracts side by side and produce a formatted Word document for lawyers to review.",
      "steps": [
        {
          "instruction": "Create `compare.py` with this code:",
          "prompt": "\"\"\"\nStep 4 of the Contract Clause Extractor (part 1) - compares two\nextracted clause sets and summarizes material differences.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\n\ndef build_prompt(clauses_a, clauses_b):\n    lines = []\n    for clause_type in sorted(set(clauses_a) | set(clauses_b)):\n        text_a = clauses_a.get(clause_type, {}).get(\"exact_text\", \"Not found\")\n        text_b = clauses_b.get(clause_type, {}).get(\"exact_text\", \"Not found\")\n        lines.append(f\"{clause_type}:\\n  Version A: {text_a}\\n  Version B: {text_b}\")\n\n    return \"Below are two contract versions' clauses, side by side. Summarize \" \\\n        \"material differences clause by clause - skip clauses that are \" \\\n        \"substantively identical. For each meaningful difference, explain what \" \\\n        \"changed and which version is more favorable to the RECEIVING party.\\n\\n\" \\\n        + \"\\n\\n\".join(lines)\n\n\ndef compare_contracts(clauses_a, clauses_b):\n    \"\"\"\n    The main function. Give it two extracted clause dicts (from\n    extract_clauses(), for two versions of a contract), get back a\n    plain-English summary of material differences.\n    \"\"\"\n    prompt = build_prompt(clauses_a, clauses_b)\n    return ask_ai(prompt, max_tokens=1500, project=\"contract-clause-extractor\")\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check prompt-building works - no AI\n    # call, no credits spent:  python compare.py\n    clauses_a = {\"Governing Law\": {\"exact_text\": \"Governed by the laws of Delaware.\"}}\n    clauses_b = {\"Governing Law\": {\"exact_text\": \"Governed by the laws of California.\"}}\n\n    prompt = build_prompt(clauses_a, clauses_b)\n    assert \"Delaware\" in prompt and \"California\" in prompt\n    assert \"Version A\" in prompt and \"Version B\" in prompt\n    print(prompt)\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python compare.py` (no AI call, no credits spent - this only tests prompt-building). You should see both contract versions' text correctly included in the prompt, ending with `All checks passed.`"
        },
        {
          "instruction": "Create `export.py` with this code:",
          "prompt": "\"\"\"\nStep 4 of the Contract Clause Extractor (part 2) - exports the clause\nreview to a formatted Word document. No AI or API key needed - this is\npure document assembly, fully testable by actually building and\nre-opening a real .docx file.\n\"\"\"\n\nfrom docx import Document\nfrom docx.shared import RGBColor\n\nRISK_COLORS = {\n    \"red\": RGBColor(0xC0, 0x00, 0x00),\n    \"yellow\": RGBColor(0xB8, 0x86, 0x0B),\n    \"green\": RGBColor(0x00, 0x80, 0x00),\n    \"unclear\": RGBColor(0x80, 0x80, 0x80),\n}\n\n\ndef export_word(clauses, output=\"contract_review.docx\"):\n    \"\"\"\n    Builds a Word document: a title, then one section per clause with a\n    color-coded risk line, a plain-English summary, and the exact quote.\n\n        export_word(clauses, output=\"review.docx\")\n    \"\"\"\n    document = Document()\n    document.add_heading(\"Contract Clause Review\", level=0)\n\n    for clause_type, data in clauses.items():\n        document.add_heading(clause_type, level=1)\n\n        risk = data.get(\"risk\", \"unclear\")\n        risk_paragraph = document.add_paragraph()\n        risk_run = risk_paragraph.add_run(f\"Risk: {risk.upper()}\")\n        risk_run.font.color.rgb = RISK_COLORS.get(risk, RISK_COLORS[\"unclear\"])\n        risk_run.bold = True\n\n        if data.get(\"verified\") is False:\n            warning = document.add_paragraph()\n            warning.add_run(\"Quote could not be verified against the source contract - check by hand.\").italic = True\n\n        document.add_paragraph(data.get(\"summary\", \"\"))\n        document.add_paragraph(data.get(\"exact_text\", \"\"))\n\n    document.save(output)\n    return output\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the Word export works - a real\n    # .docx file built, re-opened, and verified, then cleaned up:\n    #     python export.py\n    import os\n\n    clauses = {\n        \"Payment Terms\": {\"summary\": \"Net 30 payment terms.\", \"exact_text\": \"Payment due within 30 days.\", \"risk\": \"green\", \"verified\": True},\n        \"Non-Compete\": {\"summary\": \"5-year non-compete.\", \"exact_text\": \"Shall not compete for 5 years.\", \"risk\": \"red\", \"verified\": False},\n    }\n\n    path = export_word(clauses, output=\"test_review.docx\")\n    assert os.path.exists(path)\n\n    reopened = Document(path)\n    all_text = \"\\n\".join(p.text for p in reopened.paragraphs)\n    headings = [p.text for p in reopened.paragraphs if p.style.name.startswith(\"Heading\")]\n\n    assert \"Contract Clause Review\" in all_text\n    assert \"Payment Terms\" in headings\n    assert \"Non-Compete\" in headings\n    assert \"RISK: GREEN\" in all_text.upper() or \"RISK: RED\" in all_text.upper()\n    assert \"could not be verified\" in all_text\n    print(\"Re-opened the saved document and confirmed the title, both clause headings,\")\n    print(\"a risk line, and the unverified-quote warning are all present.\")\n\n    os.remove(path)\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python export.py`. You should see a real .docx file built, re-opened, and confirmed to contain the title, both clause headings, a risk line, and the unverified-quote warning - then cleaned up, ending with `All checks passed.`"
        },
        {
          "instruction": "Create `main.py` with this code, then run the full pipeline end to end:",
          "prompt": "\"\"\"\nStep 4 of the Contract Clause Extractor (part 3) - ties everything\ntogether: read, extract, score, check deviations, export.\n\nRun it with:  python main.py contract.pdf\n\"\"\"\n\nimport sys\n\nfrom export import export_word\nfrom reader import read_contract\nfrom risk import overall_risk\nfrom sdt_ai import AIError\nfrom standard_library import flag_deviations\nfrom taxonomy import CLAUSE_TYPES\n\nfrom extract import extract_clauses\n\n\ndef run(contract_path):\n    print(f\"Reading {contract_path}...\")\n    contract_text = read_contract(contract_path)\n\n    print(\"Extracting clauses...\")\n    clauses = extract_clauses(contract_text, CLAUSE_TYPES)\n\n    risk_level = overall_risk(clauses)\n    print(f\"Overall risk: {risk_level}\")\n\n    deviations = flag_deviations(clauses)\n    if deviations:\n        print(f\"{len(deviations)} clause(s) deviate from your standard library:\")\n        for clause_type in deviations:\n            print(f\"  - {clause_type}\")\n\n    unverified = [name for name, data in clauses.items() if data.get(\"verified\") is False]\n    if unverified:\n        print(f\"Warning: {len(unverified)} clause(s) have a quote that couldn't be verified against the source:\")\n        for name in unverified:\n            print(f\"  - {name}\")\n\n    output = export_word(clauses)\n    print(f\"\\nDone. Report saved to: {output}\")\n\n\nif __name__ == \"__main__\":\n    if len(sys.argv) < 2:\n        print(\"Usage: python main.py contract.pdf\")\n        sys.exit(1)\n\n    try:\n        run(sys.argv[1])\n    except AIError as problem:\n        print(f\"AI request failed:\\n{problem}\")\n    except ValueError as problem:\n        print(f\"Could not complete the pipeline:\\n{problem}\")\n",
          "verify": "Run `python main.py sample_contract.pdf`. It should produce contract_review.docx with color-coded risk levels per clause, and print any deviations from your standard library plus any clauses whose quote couldn't be verified. Run compare_contracts() on two versions of a contract and confirm it produces a readable summary of what changed."
